shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #eae3d5;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c9c1b0;
    --accent: #b85d19;
    --crimson: #9e2a2b;
    --navy-bg: #0f1d2b;
    --navy-card: #16283a;
    --navy-line: #283e54;
    --amber: #d4882a;
    --teal: #2b6f77;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
  }

  /* Language Switching Rules */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    font-family: 'Noto Serif SC', 'Lora', Georgia, serif;
    background-color: var(--paper);
    color: var(--body);
    line-height: 1.85;
    overflow-x: hidden;
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: 'Lora', Georgia, serif;
    line-height: 1.78;
  }

  /* Sticky Top Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 100;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line-strong);
  }

  .masthead-inner {
    max-width: 1180px;
    margin: 0 auto;
    padding: 0.7rem 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .brand-group {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    flex-wrap: wrap;
  }

  .wsj-mark {
    font-family: 'Playfair Display', Georgia, serif;
    font-weight: 800;
    font-size: 1.05rem;
    letter-spacing: 0.08em;
    color: var(--ink);
    text-transform: uppercase;
  }

  .brand-divider {
    width: 1px;
    height: 14px;
    background: var(--line-strong);
  }

  .section-tag {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.72rem;
    font-weight: 500;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--accent);
  }

  .lang-switch {
    display: inline-flex;
    border: 1px solid var(--line-strong);
    border-radius: 3px;
    overflow: hidden;
    background: var(--paper-card);
  }

  .lang-btn {
    border: none;
    background: transparent;
    padding: 0.32rem 0.72rem;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.75rem;
    font-weight: 600;
    color: var(--muted);
    cursor: pointer;
    transition: all 0.18s ease;
  }

  :host([lang="zh-CN"]) .lang-btn[data-lang="zh-CN"],
  :host([lang="en"]) .lang-btn[data-lang="en"] {
    background: var(--ink);
    color: var(--paper);
  }

  .progress-bar-wrap {
    height: 2px;
    width: 100%;
    background: transparent;
  }

  .progress-bar {
    height: 100%;
    width: 0%;
    background: var(--accent);
    transition: width 0.1s linear;
  }

  /* Layout Container */
  .page-container {
    max-width: 1180px;
    margin: 0 auto;
    padding: 0 1.5rem 5rem;
  }

  /* Hero Section */
  .hero {
    padding: 3.2rem 0 2.5rem;
    border-bottom: 2px solid var(--ink);
    margin-bottom: 2.5rem;
  }

  .hero-kicker-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid var(--line);
  }

  .kicker-pill {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.75rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--crimson);
  }

  .kicker-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: var(--crimson);
    display: inline-block;
  }

  .dispatch-code {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.74rem;
    color: var(--muted);
  }

  .hero-title {
    font-family: 'Noto Serif SC', 'Playfair Display', Georgia, serif;
    font-weight: 700;
    font-size: clamp(2.1rem, 4.4vw, 3.55rem);
    line-height: 1.18;
    color: var(--ink);
    letter-spacing: -0.015em;
    margin-bottom: 1.15rem;
    max-width: 980px;
  }

  :host([lang="en"]) .hero-title {
    font-family: 'Playfair Display', Georgia, serif;
    font-weight: 800;
    line-height: 1.1;
  }

  .hero-dek {
    font-family: 'Noto Sans SC', 'Lora', serif;
    font-size: clamp(1.08rem, 1.8vw, 1.35rem);
    line-height: 1.6;
    color: var(--muted);
    font-weight: 400;
    max-width: 840px;
    margin-bottom: 1.75rem;
  }

  .byline-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 1rem;
    padding-top: 1rem;
    border-top: 1px solid var(--line);
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.82rem;
    color: var(--muted);
  }

  .byline-author strong {
    color: var(--ink);
    font-weight: 700;
    letter-spacing: 0.03em;
  }

  /* Hero Situation Strip */
  .situation-strip {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1px;
    background: var(--line-strong);
    border: 1px solid var(--line-strong);
    margin-top: 1.75rem;
  }

  .situation-cell {
    background: var(--paper-card);
    padding: 1.05rem 1.2rem;
  }

  .sit-code {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--muted);
    margin-bottom: 0.3rem;
  }

  .sit-val {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-size: 1.55rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.2;
    margin-bottom: 0.25rem;
  }

  .sit-val.crimson {
    color: var(--crimson);
  }

  .sit-val.accent {
    color: var(--accent);
  }

  .sit-desc {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.78rem;
    line-height: 1.45;
    color: var(--muted);
  }

  /* Reporter Context Dossier */
  .context-dossier {
    background: var(--paper-card);
    border-left: 4px solid var(--ink);
    border-top: 1px solid var(--line);
    border-right: 1px solid var(--line);
    border-bottom: 1px solid var(--line);
    padding: 1.35rem 1.65rem;
    margin-bottom: 3rem;
    display: grid;
    grid-template-columns: 190px 1fr;
    gap: 1.5rem;
    align-items: start;
  }

  .dossier-badge {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.74rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--ink);
    padding-top: 0.2rem;
  }

  .dossier-badge span {
    display: block;
    font-weight: 400;
    color: var(--muted);
    font-size: 0.68rem;
    margin-top: 0.25rem;
  }

  .dossier-body {
    font-family: 'Noto Sans SC', 'Inter', sans-serif;
    font-size: 0.94rem;
    line-height: 1.75;
    color: var(--body);
  }

  /* Editorial Two-Column Asymmetric Grid */
  .editorial-grid {
    display: grid;
    grid-template-columns: minmax(0, 680px) minmax(280px, 390px);
    justify-content: space-between;
    gap: 3.2rem;
    align-items: start;
  }

  .prose-col {
    min-width: 0;
  }

  .rail-col {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 1.75rem;
  }

  /* Prose Styling */
  .prose-p {
    font-size: 1.125rem;
    line-height: 1.92;
    color: var(--body);
    margin-bottom: 1.55rem;
  }

  :host([lang="en"]) .prose-p {
    font-size: 1.11rem;
    line-height: 1.82;
  }

  .prose-lead {
    font-size: 1.24rem;
    line-height: 1.88;
    color: var(--ink);
    font-weight: 600;
    padding-left: 1.15rem;
    border-left: 3px solid var(--crimson);
    margin-bottom: 1.85rem;
  }

  :host([lang="en"]) .prose-lead {
    font-size: 1.22rem;
    font-weight: 400;
  }

  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, rgba(184, 93, 25, 0.22) 58%);
    color: inherit;
    padding: 0 0.12em;
    font-weight: 600;
  }

  /* Section Chapters */
  .chapter-divider {
    margin: 3.2rem 0 2rem;
    padding-top: 1.5rem;
    border-top: 2px solid var(--ink);
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.75rem;
  }

  .chapter-num {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.76rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--accent);
  }

  .chapter-title {
    font-family: 'Noto Serif SC', 'Playfair Display', serif;
    font-size: 1.45rem;
    font-weight: 700;
    color: var(--ink);
  }

  /* Side Rail Cards */
  .rail-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--ink);
    padding: 1.35rem 1.4rem;
  }

  .rail-card.alert-card {
    border-top-color: var(--crimson);
  }

  .rail-header {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.09em;
    text-transform: uppercase;
    color: var(--accent);
    margin-bottom: 0.45rem;
  }

  .rail-card.alert-card .rail-header {
    color: var(--crimson);
  }

  .rail-title {
    font-family: 'Noto Serif SC', 'Playfair Display', serif;
    font-size: 1.08rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.38;
    margin-bottom: 0.9rem;
    padding-bottom: 0.65rem;
    border-bottom: 1px solid var(--line);
  }

  /* Advisory Matrix inside Rail */
  .advisory-tier {
    margin-bottom: 1rem;
  }

  .advisory-tier:last-child {
    margin-bottom: 0;
  }

  .tier-badge {
    display: inline-block;
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.68rem;
    font-weight: 700;
    padding: 0.15rem 0.45rem;
    border-radius: 2px;
    margin-bottom: 0.4rem;
    text-transform: uppercase;
  }

  .tier-badge.severe {
    background: rgba(158, 42, 43, 0.14);
    color: var(--crimson);
    border: 1px solid rgba(158, 42, 43, 0.35);
  }

  .tier-badge.caution {
    background: rgba(184, 93, 25, 0.14);
    color: var(--accent);
    border: 1px solid rgba(184, 93, 25, 0.35);
  }

  .tier-states {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.88rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.2rem;
  }

  .tier-scope {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.8rem;
    line-height: 1.5;
    color: var(--muted);
  }

  /* Derived Pull Quote */
  .pull-quote {
    background: var(--paper-card);
    border-left: 4px solid var(--accent);
    padding: 1.35rem 1.45rem;
    margin: 0;
  }

  .quote-mark {
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 2.4rem;
    line-height: 1;
    color: var(--accent);
    margin-bottom: 0.25rem;
  }

  .quote-text {
    font-family: 'Noto Serif SC', 'Playfair Display', serif;
    font-size: 1.12rem;
    font-weight: 600;
    line-height: 1.65;
    color: var(--ink);
    margin-bottom: 0.75rem;
  }

  .quote-attrib {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.75rem;
    color: var(--muted);
    border-top: 1px solid var(--line);
    padding-top: 0.55rem;
  }

  /* Full-Bleed Tactical Map Exhibit (Dark Navy Briefing) */
  .tactical-exhibit {
    background: var(--navy-bg);
    color: #f2efe9;
    border-radius: 4px;
    padding: 2.2rem 2.2rem 1.8rem;
    margin: 3rem 0;
    border: 1px solid var(--navy-line);
    box-shadow: 0 14px 34px rgba(15, 29, 43, 0.14);
  }

  .exhibit-top {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    flex-wrap: wrap;
    gap: 1rem;
    margin-bottom: 1.35rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid var(--navy-line);
  }

  .exhibit-kicker {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.72rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: #f0a253;
    margin-bottom: 0.35rem;
  }

  .exhibit-heading {
    font-family: 'Noto Serif SC', 'Playfair Display', serif;
    font-size: 1.45rem;
    font-weight: 700;
    color: #ffffff;
    line-height: 1.3;
  }

  .exhibit-sub {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.86rem;
    color: #b4c2d0;
    margin-top: 0.3rem;
    max-width: 680px;
  }

  .exhibit-legend {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.76rem;
    color: #d6dfe8;
  }

  .legend-item {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
  }

  .legend-swatch {
    width: 14px;
    height: 4px;
    border-radius: 2px;
    display: inline-block;
  }

  .svg-frame {
    width: 100%;
    overflow: hidden;
    background: #0b1622;
    border: 1px solid var(--navy-line);
    border-radius: 3px;
    margin-bottom: 1.25rem;
  }

  .svg-frame svg {
    display: block;
    width: 100%;
    height: auto;
  }

  .exhibit-footnote {
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.75rem;
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.72rem;
    color: #8fa3b8;
  }

  /* Forensic Airport Strike Dossier Grid */
  .strike-dossier-wrap {
    margin: 2.5rem 0;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.6rem;
  }

  .strike-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1rem;
    margin-top: 1.1rem;
  }

  .strike-node {
    background: var(--paper);
    border: 1px solid var(--line);
    border-top: 3px solid var(--crimson);
    padding: 1.1rem;
  }

  .strike-node.secondary {
    border-top-color: var(--accent);
  }

  .strike-node.un-node {
    border-top-color: var(--teal);
  }

  .node-tag {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.68rem;
    font-weight: 700;
    text-transform: uppercase;
    color: var(--muted);
    margin-bottom: 0.35rem;
  }

  .node-loc {
    font-family: 'Noto Serif SC', 'Playfair Display', serif;
    font-size: 1.02rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.45rem;
  }

  .node-detail {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.82rem;
    line-height: 1.55;
    color: var(--body);
  }

  /* Carrier Reroute Comparison Table */
  .carrier-table-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--ink);
    padding: 1.4rem;
  }

  .carrier-row {
    padding: 0.85rem 0;
    border-bottom: 1px solid var(--line);
  }

  .carrier-row:last-child {
    border-bottom: none;
    padding-bottom: 0;
  }

  .carrier-name {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.86rem;
    font-weight: 700;
    color: var(--ink);
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.3rem;
  }

  .carrier-route-tag {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.68rem;
    color: var(--accent);
    background: rgba(184, 93, 25, 0.1);
    padding: 0.1rem 0.4rem;
    border-radius: 2px;
  }

  .carrier-shift {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.8rem;
    line-height: 1.5;
    color: var(--muted);
  }

  /* Climactic Dilemma Box */
  .dilemma-verdict {
    margin-top: 2rem;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-left: 5px solid var(--crimson);
    padding: 1.65rem 1.85rem;
  }

  .dilemma-label {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: var(--crimson);
    margin-bottom: 0.65rem;
  }

  /* Footer */
  .ed-footer {
    margin-top: 4.5rem;
    padding-top: 2rem;
    border-top: 2px solid var(--ink);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1rem;
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.75rem;
    color: var(--muted);
  }

  /* Responsive Mobile Reflow */
  @media (max-width: 960px) {
    .situation-strip {
      grid-template-columns: repeat(2, 1fr);
    }
    .context-dossier {
      grid-template-columns: 1fr;
      gap: 0.65rem;
    }
    .editorial-grid {
      grid-template-columns: 1fr;
      gap: 2.2rem;
    }
    .strike-grid {
      grid-template-columns: 1fr;
    }
    .tactical-exhibit {
      padding: 1.4rem 1.15rem;
    }
  }

  @media (max-width: 540px) {
    .page-container {
      padding: 0 1.05rem 3.5rem;
    }
    .masthead-inner {
      padding: 0.6rem 1.05rem;
    }
    .situation-strip {
      grid-template-columns: 1fr;
    }
    .hero {
      padding: 2rem 0 1.75rem;
    }
    .prose-lead {
      font-size: 1.12rem;
      padding-left: 0.9rem;
    }
    .prose-p {
      font-size: 1.05rem;
    }
    .dilemma-verdict {
      padding: 1.25rem 1.2rem;
    }
  }
